import{_ as o,o as t,c as e,a2 as r}from"./chunks/framework.BDCokyix.js";const g=JSON.parse('{"title":"1. Introduction and Goals","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/arc42/01-introduction-goals.md","filePath":"architecture/arc42/01-introduction-goals.md","lastUpdated":1780254295000}'),i={name:"architecture/arc42/01-introduction-goals.md"};function n(s,a,l,c,d,p){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="_1-introduction-and-goals" tabindex="-1">1. Introduction and Goals <a class="header-anchor" href="#_1-introduction-and-goals" aria-label="Permalink to &quot;1. Introduction and Goals&quot;">​</a></h1><p>Soma is a local-first workspace platform for structured note-taking and collaboration, designed for reliability, privacy, and offline-friendly workflows.</p><h2 id="stakeholders" tabindex="-1">Stakeholders <a class="header-anchor" href="#stakeholders" aria-label="Permalink to &quot;Stakeholders&quot;">​</a></h2><ul><li><strong>Members</strong>: access workspace content, take notes, and collaborate with peers.</li><li><strong>Owners/Admins</strong>: create/manage spaces, approve membership, and configure bots.</li><li><strong>Workspace operators</strong>: run optional infrastructure (bots, relay, rendezvous) and manage updates.</li><li><strong>Developers</strong>: extend the desktop apps, peer protocols, and storage.</li></ul><h2 id="primary-goals" tabindex="-1">Primary goals <a class="header-anchor" href="#primary-goals" aria-label="Permalink to &quot;Primary goals&quot;">​</a></h2><ul><li><strong>Local-first</strong>: operate without a mandatory cloud backend.</li><li><strong>Offline-capable</strong>: work on LAN-only networks and degrade gracefully on poor internet.</li><li><strong>Decentralized collaboration</strong>: peer-to-peer networking with optional &quot;connectivity-only&quot; infra.</li><li><strong>Capability-based security</strong>: membership without accounts/passwords; explicit delegation to bots.</li><li><strong>Fast UX</strong>: responsive desktop apps with background networking handled by a daemon.</li></ul><h2 id="quality-goals-top" tabindex="-1">Quality goals (top) <a class="header-anchor" href="#quality-goals-top" aria-label="Permalink to &quot;Quality goals (top)&quot;">​</a></h2><ul><li><strong>Security</strong>: minimize exposed network surfaces on desktop; verify blob integrity by CID; signed capabilities.</li><li><strong>Availability</strong>: optional always-on bots (VDFs) improve availability/latency by caching.</li><li><strong>Operability</strong>: small number of binaries with health/metrics endpoints; container-friendly server daemons.</li><li><strong>Maintainability</strong>: shared Rust workspace crates; clear separation between controllers (IPC/HTTP) and business logic.</li></ul>',8)])])}const h=o(i,[["render",n]]);export{g as __pageData,h as default};
